import{_ as t,o as a,c as s,ao as i}from"./chunks/framework.DUdA5YZf.js";const g=JSON.parse('{"title":"Dual numbers: BLAS-1 for forward-mode AD","description":"","frontmatter":{},"headers":[],"relativePath":"dual.md","filePath":"dual.md","lastUpdated":null}'),o={name:"dual.md"};function n(d,e,l,r,h,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="Dual-numbers:-BLAS-1-for-forward-mode-AD" tabindex="-1">Dual numbers: BLAS-1 for forward-mode AD <a class="header-anchor" href="#Dual-numbers:-BLAS-1-for-forward-mode-AD" aria-label="Permalink to &quot;Dual numbers: BLAS-1 for forward-mode AD {#Dual-numbers:-BLAS-1-for-forward-mode-AD}&quot;">​</a></h1><p>Status: <strong>design agreed, not yet implemented.</strong> This page records the design, the measurements it rests on, and the decisions taken — including the ones that closed off tempting alternatives.</p><p><code>ForwardDiff.Dual{Tag,V,1}</code> and <code>Complex{V}</code> have <strong>byte-identical memory layout</strong>, so PureBLAS can serve forward-mode AD from the same SIMD machinery it uses for complex. Nothing else in the Julia ecosystem ships a BLAS optimised for array-of-structs dual numbers; ForwardDiff users currently fall through to scalar loops because <code>Dual</code> is not a <code>BlasFloat</code>.</p><h2 id="The-layout-fact-this-rests-on" tabindex="-1">The layout fact this rests on <a class="header-anchor" href="#The-layout-fact-this-rests-on" aria-label="Permalink to &quot;The layout fact this rests on {#The-layout-fact-this-rests-on}&quot;">​</a></h2><p>Verified 2026-09-12 on Julia 1.13.0 / ForwardDiff:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">sizeof</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Dual{Nothing,Float64,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 16</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> sizeof</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ComplexF64)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">reinterpret</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Float64, [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Dual{Nothing}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Dual{Nothing}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)]) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>Same as <code>reinterpret(Float64, ComplexF64[1+2im, 3+4im])</code>. <code>Dual</code> is <code>value::V</code> + <code>partials::Partials{N,V}</code> wrapping an <code>NTuple{N,V}</code>, so at <code>N = 1</code> it is exactly an interleaved pair. Every load, store, stride, alignment and in-lane shuffle transfers unchanged.</p><p>The extension asserts this at load time (<code>sizeof == 16 &amp;&amp; fieldoffset(..., 2) == 8</code>), so a future ForwardDiff layout change becomes a load error rather than silent garbage.</p><h2 id="The-trap-the-layout-creates" tabindex="-1">⛔ The trap the layout creates <a class="header-anchor" href="#The-trap-the-layout-creates" aria-label="Permalink to &quot;⛔ The trap the layout creates {#The-trap-the-layout-creates}&quot;">​</a></h2><p>Because the layouts are bit-identical it is tempting to <code>reinterpret</code> a <code>Vector{Dual}</code> to <code>Vector{ComplexF64}</code> and call the complex kernel. <strong>That is wrong wherever two elements multiply.</strong></p><table tabindex="0"><thead><tr><th style="text-align:right;"></th><th style="text-align:right;">product</th><th style="text-align:right;">real part / value</th></tr></thead><tbody><tr><td style="text-align:right;">complex</td><td style="text-align:right;"><code>(a+bi)(c+di)</code></td><td style="text-align:right;"><code>ac − bd</code></td></tr><tr><td style="text-align:right;">dual</td><td style="text-align:right;"><code>(a+bε)(c+dε)</code></td><td style="text-align:right;"><code>ac</code> (ε² = 0)</td></tr></tbody></table><p>Reinterpreting silently subtracts <code>bd</code> from the value. It is only valid where no element × element product occurs: <code>copy</code>, <code>swap</code>, <code>axpy</code> with a <strong>real</strong> alpha, <code>scal</code> by a <strong>real</strong> alpha.</p><p>The ε²-leak test exists to catch exactly this: run <code>dot(x,x)</code> with partials ~<code>1e155</code> so <code>Σ x_p²</code> overflows. The value must stay finite and the partial must equal <code>2 Σ x_v x_p</code>. A reinterpreted complex kernel fails it.</p><h2 id="Dual-needs-3-multiplies,-complex-needs-4-does-not-survive-into-SIMD" tabindex="-1">⛔ &quot;Dual needs 3 multiplies, complex needs 4&quot; does not survive into SIMD <a class="header-anchor" href="#Dual-needs-3-multiplies,-complex-needs-4-does-not-survive-into-SIMD" aria-label="Permalink to &quot;⛔ &quot;Dual needs 3 multiplies, complex needs 4&quot; does not survive into SIMD {#&quot;Dual-needs-3-multiplies,-complex-needs-4&quot;-does-not-survive-into-SIMD}&quot;">​</a></h2><p>The scalar op counts are real — dual multiply is <code>ac</code>, <code>ad + bc</code>; complex is <code>ac − bd</code>, <code>ad + bc</code> — but in the interleaved swap-adjacent form both algebras are the same two FMAs and one shuffle:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">muladd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">shuffle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(x), sgn, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">muladd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(x, arv, y))</span></span></code></pre></div><p>with <code>sgn = [−b, +b, …]</code> for complex and <code>[0, +b, …]</code> for dual. The second FMA runs over the whole vector either way. <strong>The dual advantage is a scalar-op-count fact, not a kernel fact</strong>, and the design does not claim otherwise.</p><h2 id="Measured:-where-dual-actually-loses-today" tabindex="-1">Measured: where dual actually loses today <a class="header-anchor" href="#Measured:-where-dual-actually-loses-today" aria-label="Permalink to &quot;Measured: where dual actually loses today {#Measured:-where-dual-actually-loses-today}&quot;">​</a></h2><p>Dual GB/s ÷ the complex twin&#39;s GB/s on identical bytes, through the real PureBLAS entries (wintermute, Julia 1.13.0, scratch env — adequate for an order-of-magnitude decision, <strong>not</strong> a gate number):</p><table tabindex="0"><thead><tr><th style="text-align:right;">op</th><th style="text-align:right;">n=1e3</th><th style="text-align:right;">n=1e4</th><th style="text-align:right;">n=1e5</th><th style="text-align:right;">n=1e6</th></tr></thead><tbody><tr><td style="text-align:right;">axpy</td><td style="text-align:right;">0.82</td><td style="text-align:right;">0.80</td><td style="text-align:right;">1.03</td><td style="text-align:right;">1.00</td></tr><tr><td style="text-align:right;">scal</td><td style="text-align:right;">0.69</td><td style="text-align:right;">0.65</td><td style="text-align:right;">0.77</td><td style="text-align:right;">0.99</td></tr><tr><td style="text-align:right;">dot</td><td style="text-align:right;">0.37</td><td style="text-align:right;">0.34</td><td style="text-align:right;">0.49</td><td style="text-align:right;">0.92</td></tr><tr><td style="text-align:right;">asum</td><td style="text-align:right;">0.21</td><td style="text-align:right;">0.18</td><td style="text-align:right;">0.23</td><td style="text-align:right;">0.61</td></tr><tr><td style="text-align:right;">iamax</td><td style="text-align:right;">0.37</td><td style="text-align:right;">0.29</td><td style="text-align:right;">0.29</td><td style="text-align:right;">0.36</td></tr><tr><td style="text-align:right;"><strong>nrm2</strong></td><td style="text-align:right;"><strong>0.07</strong></td><td style="text-align:right;"><strong>0.06</strong></td><td style="text-align:right;"><strong>0.08</strong></td><td style="text-align:right;"><strong>0.20</strong></td></tr></tbody></table><p><code>nrm2</code> is flat at <strong>4.8 GB/s at every n</strong> — 13–16× slower than complex. Flat in <code>n</code> means it is not memory-bound: neither fast branch applies (<code>_simd1</code> is <code>BlasReal</code>-only, <code>_cplx_re</code> is <code>Complex</code>-only), so it falls to the <code>lassq</code> scaling loop, <code>_nrm2_acc</code> per element with a division and branches.</p><p><strong>This is what sets the scope.</strong> The reductions are the prize; <code>axpy</code>/<code>scal</code> converge to parity past L2 and are only 20–35% down in cache.</p><h2 id="The-dupEven-formulation" tabindex="-1">The <code>dupEven</code> formulation <a class="header-anchor" href="#The-dupEven-formulation" aria-label="Permalink to &quot;The \`dupEven\` formulation {#The-dupEven-formulation}&quot;">​</a></h2><p>Rather than the swap-adjacent shuffle, dual reductions use an <strong>in-lane duplicate-even</strong> shuffle <code>(0,0,2,2,…)</code>, so <code>dupEven(v) = [x_v, x_v]</code> per pair. Same cost class as the swap, and it lands the useful quantity in both lanes:</p><table tabindex="0"><thead><tr><th style="text-align:right;">op</th><th style="text-align:right;">body</th><th style="text-align:right;">parity fold gives</th></tr></thead><tbody><tr><td style="text-align:right;">nrm2</td><td style="text-align:right;"><code>acc = muladd(v, dupEven(v), acc)</code></td><td style="text-align:right;"><code>[Σ x_v², Σ x_v·x_p]</code> — one FMA, no wasted lanes</td></tr><tr><td style="text-align:right;">asum</td><td style="text-align:right;"><code>acc += flipsign(v, dupEven(v))</code></td><td style="text-align:right;"><code>[Σ|x_v|, Σ sign(x_v)·x_p]</code> — no blend</td></tr><tr><td style="text-align:right;">iamax</td><td style="text-align:right;">magnitude <code>= abs(dupEven(v))</code></td><td style="text-align:right;">value magnitude broadcast to both lanes</td></tr></tbody></table><p><code>flipsign</code> uses the sign <strong>bit</strong>, matching ForwardDiff&#39;s <code>abs</code> derivative (<code>signbit(x) ? -1 : 1</code>) bit-for-bit at ±0.0.</p><p><code>dupEven</code> also removes a NaN hazard. With <code>sgn = [0, b, …]</code> the even lane computes <code>t + 0·x_p</code>, so an infinite partial makes <code>0·Inf = NaN</code> poison the <strong>value</strong>. Putting the <code>0·</code> on the value lane instead means it only misbehaves when the value is already <code>Inf</code>, where the scalar result is <code>Inf</code> too.</p><h2 id="Per-op-decisions" tabindex="-1">Per-op decisions <a class="header-anchor" href="#Per-op-decisions" aria-label="Permalink to &quot;Per-op decisions {#Per-op-decisions}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">op</th><th style="text-align:right;">dual implementation</th><th style="text-align:right;">semantics</th></tr></thead><tbody><tr><td style="text-align:right;">copy, swap</td><td style="text-align:right;">route to <code>_copy_simd!</code>/<code>_swap_simd!</code> over 2n reals</td><td style="text-align:right;">no arithmetic</td></tr><tr><td style="text-align:right;">axpy, scal</td><td style="text-align:right;">shared tagged body; real-alpha bypass to the real kernel over 2n</td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;">dotu</td><td style="text-align:right;">shared body, per-algebra epilogue</td><td style="text-align:right;">value <code>= Σ x_v y_v</code>; the <code>Σ x_p y_p</code> lane is the ε² term and is <strong>discarded</strong></td></tr><tr><td style="text-align:right;">dotc</td><td style="text-align:right;">identical to dotu</td><td style="text-align:right;"><code>Dual &lt;: Real</code> and ForwardDiff defines no <code>conj</code>, so <code>conj(::Real) = x</code>. <strong>The ring involution <code>a − bε</code> is wrong for AD</strong>: <code>dot(x,x)</code> would give <code>Σa²</code> with a zero partial, i.e. <code>d‖x‖²/dx = 0</code></td></tr><tr><td style="text-align:right;">nrm2</td><td style="text-align:right;">standalone; <code>dupEven</code> body, not the complex <code>_sumsq_simd</code></td><td style="text-align:right;"><code>√(Σx_v²) + (Σ x_v x_p / ‖x_v‖) ε</code>. Fast path guards <code>isfinite(ss) &amp;&amp; !iszero(ss) &amp;&amp; isfinite(sp)</code>; falls back to the existing Dual lassq loop only on overflow</td></tr><tr><td style="text-align:right;">asum</td><td style="text-align:right;">standalone; <code>dupEven</code> + <code>flipsign</code></td><td style="text-align:right;">value <code>Σ|x_v|</code>, partial <code>Σ flipsign(x_p, x_v)</code></td></tr><tr><td style="text-align:right;">iamax</td><td style="text-align:right;">magnitude functor on the existing argmax scaffold</td><td style="text-align:right;"><strong>argmax of <code>|value|</code>, first occurrence on ties</strong> — see below</td></tr></tbody></table><p><code>N ≠ 1</code>, nested duals, and non-<code>BlasReal</code> <code>V</code> miss the routing predicate and take the generic scalar loop unchanged. Generalising to <code>N &gt; 1</code> is a different layout (stride <code>N+1</code>, not a pair) and is out of scope.</p><h3 id="iamax:-a-deliberate,-user-visible-semantics-change" tabindex="-1">iamax: a deliberate, user-visible semantics change <a class="header-anchor" href="#iamax:-a-deliberate,-user-visible-semantics-change" aria-label="Permalink to &quot;iamax: a deliberate, user-visible semantics change {#iamax:-a-deliberate,-user-visible-semantics-change}&quot;">​</a></h3><p><code>abs(::Dual)</code> returns a <strong>Dual</strong>, and ForwardDiff&#39;s <code>isless</code> is lexicographic — value first, then partials. So when two elements have equal magnitude, the current generic loop breaks the tie <strong>on the derivative</strong>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Dual</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Dual</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)]   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># identical magnitude 3.0</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">argmax</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">abs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.(x))              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2  — decided by the partial</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">argmax</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">abs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">value</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.(x)))      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1  — first occurrence, real-BLAS semantics</span></span></code></pre></div><p>A partial is an infinitesimal and carries no magnitude information, so letting it decide means the answer depends on the seed direction. It matters because <strong><code>iamax</code> is the pivot-selection primitive in <code>getrf</code></strong>: a pivot chosen by perturbation direction can make the LU pivot sequence differ between the primal and the AD run on identical input, and forward-mode derivatives of a pivoted factorisation assume the sequence is locally constant. Nothing is lost by ignoring partials — the return type is an <code>Int</code>.</p><p><strong>Decision (user, 2026-09-12): value-only, first occurrence, matching real BLAS.</strong> <code>_l1v</code> is added so the scalar and SIMD paths agree.</p><h2 id="Performance-bar" tabindex="-1">Performance bar <a class="header-anchor" href="#Performance-bar" aria-label="Permalink to &quot;Performance bar {#Performance-bar}&quot;">​</a></h2><p>Not &quot;dual ≥ complex&quot; uniformly — that is too weak in places and unachievable in others. Honest per-vector op counts:</p><table tabindex="0"><thead><tr><th style="text-align:right;">op</th><th style="text-align:right;">dual</th><th style="text-align:right;">complex</th></tr></thead><tbody><tr><td style="text-align:right;">nrm2</td><td style="text-align:right;">shuffle + FMA</td><td style="text-align:right;">FMA</td></tr><tr><td style="text-align:right;">asum</td><td style="text-align:right;">shuffle + flipsign + add</td><td style="text-align:right;">abs + add</td></tr><tr><td style="text-align:right;">iamax</td><td style="text-align:right;">shuffle + abs</td><td style="text-align:right;">abs + shuffle + add</td></tr><tr><td style="text-align:right;">dot, axpy, scal</td><td style="text-align:right;">identical</td><td style="text-align:right;">identical</td></tr></tbody></table><p>Complex <code>asum</code> is <code>Σ\\|Re\\|+\\|Im\\|</code> (<code>core.jl:217-218</code>) — <strong>not</strong> the modulus — so it is already the minimal real kernel over 2n reals, and dual cannot beat it: dual must move data across the lane pair and complex need not. The bar is therefore:</p><ul><li><p><strong>equal</strong> to the twin at every n for dot/axpy/scal/copy/swap;</p></li><li><p><strong>strictly greater in L1/L2</strong> for iamax (dual drops one op; <code>simd_kernels.jl:1043-1050</code> measured one deleted op as +21% at n=1e3);</p></li><li><p><strong>equal past L2</strong> for nrm2/asum, and in-cache within the cost of the extra op — priced with <code>mca_report</code> before anyone calls it a limit.</p></li></ul><h2 id="Architecture" tabindex="-1">Architecture <a class="header-anchor" href="#Architecture" aria-label="Permalink to &quot;Architecture {#Architecture}&quot;">​</a></h2><p><code>PairAlgebra</code> as a type <em>hierarchy</em> was dropped: the largest win (nrm2) shares nothing with complex, so an abstraction spanning all ops would not have earned its place. What survives is a codegen-time <strong>multiply-rule tag</strong> on the three generated bodies where dual and complex differ only by constants or epilogue — <code>_dot_cmplx_simd</code>, <code>_axpy_cmplx_{phase,wide}!</code>, <code>_scal_cmplx_simd!</code>.</p><p>It earns that on <code>dot</code> (3× in cache, byte-identical complex body) and because every future complex arm — the <code>U = 8</code> band arm, a DRAM prefetch arm — then lands on dual for free. A separate copy would silently miss both.</p><p>The tag and its singletons live in <strong>PureBLAS, not the extension</strong>: a <code>@generated</code> body runs at the world age of its own definition, so a codegen hook defined later in an extension would be invisible inside the generator. The tag needs no ForwardDiff knowledge — it is &quot;zero even lanes&quot;.</p><p><code>Expr(:meta, :inline)</code> stays inside returned generator bodies; <code>@inline</code> does not propagate into <code>@generated</code> CodeInfo.</p><h2 id="The-extension" tabindex="-1">The extension <a class="header-anchor" href="#The-extension" aria-label="Permalink to &quot;The extension {#The-extension}&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[weakdeps]  ForwardDiff = &quot;...&quot;</span></span>
<span class="line"><span>[extensions] PureBLASForwardDiffExt = &quot;ForwardDiff&quot;</span></span></code></pre></div><p>Five one-line methods and <strong>no kernels</strong>: <code>_pairalg</code>, <code>_pairreal</code>, <code>_parts</code>, <code>_mkpair</code>, <code>_l1v</code>, plus the layout assert. ForwardDiff never enters <code>[deps]</code>, so the <code>--trim</code> build never loads it and <code>libpureblas.so</code> is unaffected.</p><p><code>Tag</code> is never inspected. The only Duals the fast path constructs carry <code>x</code>&#39;s own tag, exactly as the scalar path does today via <code>convert</code>; a mixed-tag alpha fails in <code>convert</code> identically on both paths.</p><h2 id="Implementation-sequence" tabindex="-1">Implementation sequence <a class="header-anchor" href="#Implementation-sequence" aria-label="Permalink to &quot;Implementation sequence {#Implementation-sequence}&quot;">​</a></h2><p>Deliberately ordered so a complex regression can never be confounded with the dual work. 2. <strong>Complex only, no dual code.</strong> Parameterise <code>U</code> in <code>_axpy_cmplx_phase!</code> (currently hardcoded 4 at <code>simd_kernels.jl:471</code>, while real axpy has a <code>U = 8</code> band arm) — Derive <code>min(8, (_NVREG−4)÷3)</code>, which reproduces today&#39;s AVX2 code exactly. A/B at n=2e4/3e4/6e4 with real axpy at 6e4 as the L2-edge control. Route complex copy/swap off the scalar loop. Real-alpha zaxpy bypass, measured at n=1e3 and dropped if it costs. Add a <code>zscalc</code> bench row. Gate, commit.</p><ol start="3"><li><p><strong>Extension + standalone dual kernels</strong>: routing, then nrm2 (the 13×), asum, iamax. No complex arithmetic kernel is touched.</p></li><li><p><strong>Tagged shared bodies</strong>, dot first, then axpy/scal. Each op its own commit, guarded by complex <code>code_native</code> byte-identity against the post-step-1 baseline plus an opcode-histogram equality test between the complex and dual instantiations. If complex moves by one instruction, that op ships as a copy under the histogram test instead.</p></li></ol><h2 id="What-this-does-NOT-fix" tabindex="-1">What this does NOT fix <a class="header-anchor" href="#What-this-does-NOT-fix" aria-label="Permalink to &quot;What this does NOT fix {#What-this-does-NOT-fix}&quot;">​</a></h2><p>Stated plainly because the complex gate gaps motivated the work and mostly are not complex-kernel gaps:</p><ul><li><p><strong>zscal is not a complex kernel problem.</strong> The gate row scales by <code>1.0000001 + 0im</code> (<code>bench/plots.jl:1231</code>), and <code>_scal!</code> routes a real alpha to the real kernel over 2n reals (<code>level1.jl:33-37</code>). Every zscal cell is the real-scal L2/L3-edge notch. <code>_scal_cmplx_simd!</code> has <strong>no gate coverage at all</strong> — hence the new <code>zscalc</code> row in step 1.</p></li><li><p><strong>zaxpy past L3 on Zen5 tracks real axpy</strong> (0.921/0.919 vs 0.925/0.949 at n=3e5/1e6) — memory system, not algebra.</p></li><li><p><strong>zdotu Zen5 at n=1e6</strong> is a DRAM-regime question for a roofline decomposition, not a kernel.</p></li></ul><p>The one genuinely complex-specific cell is <strong>zaxpy@3e4</strong> (Zen4 0.963, Zen5 0.834), which step 1 targets.</p><p>⚠ Zen5 (neuromancer) is not gate-authoritative: its lock drops on power change, and it reads <strong>FP256</strong> (<code>test/autotune_tests.jl:21-23</code> — Strix/Krackan, <code>fpw = 32</code>, double-pumped, lands with Zen4). Do not build a width argument on &quot;Zen5 is native-512&quot;; that is a retracted claim from an old family lookup.</p>`,57)])])}const u=t(o,[["render",n]]);export{g as __pageData,u as default};
